func TestAddDirectoryToEntries_SkipsSymlinkedDirectories(t *testing.T) {
	t.Parallel()
	tempDir := t.TempDir()

	repo, err := git.PlainInit(tempDir, false)
	if err != nil {
		t.Fatalf("failed to init git repo: %v", err)
	}

